python3 -c "
import fitz, docx, os

def dump_pdf(path):
    print('=== PDF:', path, '===')
    doc = fitz.open(path)
    for i, page in enumerate(doc):
        print(f'--- Page {i+1} ---')
        print(page.get_text())

for root, dirs, files in sorted(os.walk('/filesystem/final_batch4__structural_task5_wind_diaphragm_shear__blind/project')):
    for f in sorted(files):
        p = os.path.join(root, f)
        if f.endswith('.pdf'):
            dump_pdf(p)
        elif f.endswith('.docx'):
            print('=== DOCX:', p, '===')
            d = docx.Document(p)
            for para in d.paragraphs:
                if para.text.strip():
                    print(para.text)
            for t in d.tables:
                for row in t.rows:
                    print([c.text.strip() for c in row.cells])
"

