import openpyxl, os, glob

base = '/filesystem/final_batch4__structural_task5_wind_diaphragm_shear__blind'
for p in sorted(glob.glob(base + '/**/*.xlsx', recursive=True)):
    print('=== XLSX:', os.path.relpath(p, base), '===')
    wb = openpyxl.load_workbook(p, data_only=True)
    for name in wb.sheetnames:
        print('  Sheet:', name)
        ws = wb[name]
        for r in list(ws.iter_rows(values_only=True))[:40]:
            if any(x is not None for x in r):
                print('   ', r)
"

