python3 -c "
import re
base = '/filesystem/final_batch4__structural_task5_wind_diaphragm_shear__blind'
with open(base + '/project/20_survey/NDDC-A2_Federated_Model_2026.ifc') as f:
    lines = f.read().splitlines()

props = {}
for line in lines:
    m = re.match(r'#(\d+)=IFCPROPERTYSINGLEVALUE\(\'([^\']+)\',\$,IFC\w+\(([^\)]+)\),\$\);', line)
    if m:
        props[int(m.group(1))] = (m.group(2), m.group(3).strip(\"'\"))

for line in lines:
    if 'IFCPROPERTYSET' in line or 'IFCOPENINGELEMENT' in line or 'IFCSLAB' in line:
        print(line)
        m = re.search(r'\((#\d+(?:,#\d+)*)\)\);$', line)
        if m:
            ids = [int(x[1:]) for x in m.group(1).split(',')]
            print('  ->', {props[i][0]: props[i][1] for i in ids if i in props})
"

