import sys
sys.path.insert(0, "/tmp")
import opt_design as od

z_cur = {
    "Z11": "D22-36/7-2", "Z12": "D22-36/7-2", "Z13": "D22-36/7-2",
    "Z21": "D22-36/7-2", "Z22": "D22-36/4-2", "Z23": "D22-36/4-4",
    "Z31": "D22-36/7-2", "Z32": "D22-36/7-4", "Z33": "D22-36/7-2",
    "Z41": "D22-36/7-2", "Z42": "D22-36/7-2", "Z43": "D22-36/7-2",
}
c_cur = {cid: "PL3x3/8" for cid, _, _, _ in od.chord_segs}
c_cur["C-N1"] = "PL5x1/2"
c_cur["C-N2"] = "PL5x1/2"
c_cur["C-E2"] = "PL12x1"

res_cur, _ = od.fast_eval(z_cur, c_cur)
deck_choices = ["D22-36/4-2", "D22-36/4-4", "D22-36/7-2", "D22-36/7-4"]
chord_choices = ["PL3x3/8", "PL4x3/8", "PL5x1/2", "PL6x1/2", "PL8x1/2", "PL10x3/4", "PL12x3/4", "PL12x1"]

for step in range(4):
    changed = False
    for z1 in od.zone_areas:
        for d1 in deck_choices:
            for z2 in od.zone_areas:
                for d2 in deck_choices:
                    zt = dict(z_cur)
                    zt[z1] = d1
                    zt[z2] = d2
                    if len(set(zt.values())) > 4: continue
                    r, msg = od.fast_eval(zt, c_cur)
                    if r and r[0] < res_cur[0] - 0.01:
                        res_cur, z_cur, changed = r, zt, True
                        print(f"Step {step} Z: ${r[0]:,.2f} | dy={r[1]:.4f} | b1={r[2]:.4f} | e={r[5]} td={r[6]}")
                        print("  z =", z_cur)
    for c1, _, _, _ in od.chord_segs:
        for s1 in chord_choices:
            ct = dict(c_cur)
            ct[c1] = s1
            r, msg = od.fast_eval(z_cur, ct)
            if r and r[0] < res_cur[0] - 0.01:
                res_cur, c_cur, changed = r, ct, True
                non_def = {k:v for k,v in c_cur.items() if v != "PL3x3/8"}
                print(f"Step {step} C: ${r[0]:,.2f} | dy={r[1]:.4f} | b1={r[2]:.4f} | e={r[5]} td={r[6]} | {non_def}")
    if not changed:
        break
'

